import { StimpactClient } from "@stimpact/sdk";

type HandledErrorInput = {
  error: unknown;
  request?: { method?: string; url?: string };
  response?: { status_code?: number };
};

const stimpactClient = new StimpactClient({
  apiBaseUrl: import.meta.env.VITE_STIMPACT_API_BASE_URL,
  browserToken: import.meta.env.VITE_STIMPACT_BROWSER_TOKEN,
  environment: import.meta.env.MODE,
  service: "soul-song-service-client",
});

export async function captureHandledError(input: HandledErrorInput): Promise<void> {
  try {
    const error = input.error instanceof Error ? input.error : new Error(String(input.error));
    await stimpactClient.captureError({
      error,
      handled: true,
      metadata: {
        request: input.request,
        response: input.response,
      },
    });
  } catch {
    // Never let telemetry reporting break the app.
  }
}

